  it("honors If-Range with strong ETags and exact dates", async () => {
    setup();
    const range = "bytes=0-99";
    const lastModified = new Date(1_700_000_000_000).toUTCString();

    const cases: [string, number][] = [
      ['"v1"', 206],
      ['"v0"', 200],
      ['W/"v1"', 200],
      [lastModified, 206],
      [new Date(1_700_000_000_000 - 1000).toUTCString(), 200],
      ["yesterday", 200],
