it("ranges the selected precompressed variant", async () => {
  // Ranges address the encoded bytes (RFC 9110 section 14.2), so the variant must be
  // real gzip for the client to decode the full-length response.
  const payload = "gz".repeat(20);
  const gz = gzipSync(payload);
  const files: Record<string, Uint8Array | string> = {
    "/pre/app.js": body,
    "/pre/app.js.gz": gz,
  };
  const setupVariant = () =>
    setup({
      getMeta: vi.fn((id) =>
        files[id] === undefined
          ? undefined
          : {
              type: "text/javascript",
              etag: '"v1"',
              size: files[id].length,
              encoding: id.endsWith(".gz") ? "gzip" : undefined,
            },
      ),
      getContents: vi.fn((id) => files[id]),
      encodings: { gzip: ".gz" },
    });
  setupVariant();

  const partial = await t.fetch("/pre/app.js", {
    headers: { "accept-encoding": "gzip", range: "bytes=0-9" },
  });
  expect(partial.status).toBe(206);
  expect(partial.headers.get("content-encoding")).toBe("gzip");
  expect(partial.headers.get("content-length")).toBe("10");
  expect(partial.headers.get("content-range")).toBe(`bytes 0-9/${gz.length}`);
  expect(partial.headers.get("vary")).toBe("accept-encoding");
  await partial.body?.cancel();

  const full = await t.fetch("/pre/app.js", {
    headers: { "accept-encoding": "gzip", range: `bytes=0-${gz.length - 1}` },
  });
  expect(full.status).toBe(206);
  expect(await full.text()).toBe(payload);
});

